<?php
namespace Tests\Feature;
use App\Models\Branch; use App\Models\Employee; use App\Models\Tenant; use App\Models\User; use App\Services\EmployeeImportService; use App\Services\SpreadsheetReader; use Illuminate\Support\Str; use Tests\TestCase;
class SpreadsheetImportTest extends TestCase { public function test_csv_reader_and_employee_import_validate_and_preserve_salary_history():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Import '.Str::random(5)]);$tmp=tempnam(sys_get_temp_dir(),'payra-import-');try{tenancy()->initialize($tenant);$u=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);Branch::create(['code'=>'AMM','name'=>'Amman']);file_put_contents($tmp,"name,national_id,hire_date,salary,branch_code\nImported User,IMP-001,2026-01-01,600.000,AMM\n");$rows=app(SpreadsheetReader::class)->read($tmp,'csv');$batch=app(EmployeeImportService::class)->import($rows,'employees.csv',$u->id);$this->assertSame('completed',$batch->status);$e=Employee::where('national_id','IMP-001')->firstOrFail();$this->assertSame('600.000',$e->salary);$this->assertSame('AMM',$e->branch->code);$this->assertDatabaseHas('employee_salary_histories',['employee_id'=>$e->id,'amount'=>'600.000']);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();@unlink($tmp);}} }
